/**
 * Unit tests for FastDateFormat.applyRules.
 * Since applyRules is protected and relies on the internal mRules array,
 * we use reflection to inject mock rules to ensure maximum coverage.
 */
@RunWith(MockitoJUnitRunner.class)
public class FastDateFormat_applyRules_TriageGen2Test {

    @Test
    public void testApplyRules_WithMultipleRules() throws Exception {
        // Arrange
        FastDateFormat fdf = FastDateFormat.getInstance("yyyy-MM-dd");
        Calendar calendar = Calendar.getInstance();
        StringBuffer buf = new StringBuffer();

        // Mock Rule objects
        Rule rule1 = mock(Rule.class);
        Rule rule2 = mock(Rule.class);

        // Define behavior for rules
        doAnswer(invocation -> {
            StringBuffer sb = invocation.getArgument(0);
            sb.append("Rule1");
            return null;
        }).when(rule1).appendTo(any(StringBuffer.class), any(Calendar.class));

        doAnswer(invocation -> {
            StringBuffer sb = invocation.getArgument(0);
            sb.append("Rule2");
            return null;
        }).when(rule2).appendTo(any(StringBuffer.class), any(Calendar.class));

        // Inject rules into the private field mRules using reflection
        Rule[] rulesArray = new Rule[]{rule1, rule2};
        setPrivateField(fdf, "mRules", rulesArray);

        // Act
        // Since applyRules is protected, we access it via a subclass or reflection
        // For testing purposes in this context, we assume the test class can access it 
        // or we use a helper method.
        StringBuffer result = invokeApplyRules(fdf, calendar, buf);

        // Assert
        assertEquals("Rule1Rule2", result.toString());
        verify(rule1, times(1)).appendTo(buf, calendar);
        verify(rule2, times(1)).appendTo(buf, calendar);
    }

    @Test
    public void testApplyRules_WithEmptyRules() throws Exception {
        // Arrange
        FastDateFormat fdf = FastDateFormat.getInstance("yyyy");
        Calendar calendar = Calendar.getInstance();
        StringBuffer buf = new StringBuffer("Initial");

        // Inject empty rules array
        Rule[] rulesArray = new Rule[0];
        setPrivateField(fdf, "mRules", rulesArray);

        // Act
        StringBuffer result = invokeApplyRules(fdf, calendar, buf);

        // Assert
        assertEquals("Initial", result.toString());
    }

    @Test
    public void testApplyRules_SingleRule() throws Exception {
        // Arrange
        FastDateFormat fdf = FastDateFormat.getInstance("yyyy");
        Calendar calendar = Calendar.getInstance();
        StringBuffer buf = new StringBuffer();

        Rule rule = mock(Rule.class);
        doAnswer(invocation -> {
            StringBuffer sb = invocation.getArgument(0);
            sb.append("Single");
            return null;
        }).when(rule).appendTo(any(StringBuffer.class), any(Calendar.class));

        setPrivateField(fdf, "mRules", new Rule[]{rule});

        // Act
        StringBuffer result = invokeApplyRules(fdf, calendar, buf);

        // Assert
        assertEquals("Single", result.toString());
        verify(rule, times(1)).appendTo(buf, calendar);
    }

    // --- Helper Methods for Reflection ---

    private void setPrivateField(Object target, String fieldName, Object value) throws Exception {
        Field field = target.getClass().getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(target, value);
    }

    private StringBuffer invokeApplyRules(FastDateFormat fdf, Calendar calendar, StringBuffer buf) throws Exception {
        java.lang.reflect.Method method = FastDateFormat.class.getDeclaredMethod("applyRules", Calendar.class, StringBuffer.class);
        method.setAccessible(true);
        return (StringBuffer) method.invoke(fdf, calendar, buf);
    }
}
